using System;using System.Diagnostics;using System.IO;using System.Linq;using System.Threading;using System.Windows.Automation;using System.Drawing;using System.Runtime.InteropServices;
class DesktopDriver {
 [DllImport("user32.dll")]static extern bool PrintWindow(IntPtr h,IntPtr dc,uint flags);
 static AutomationElement Window(int pid){for(int i=0;i<80;i++){foreach(AutomationElement w in AutomationElement.RootElement.FindAll(TreeScope.Descendants,new AndCondition(new PropertyCondition(AutomationElement.ProcessIdProperty,pid),new PropertyCondition(AutomationElement.ControlTypeProperty,ControlType.Window))))if(w.Current.IsEnabled&&w.Current.ControlType==ControlType.Window&&w.Current.BoundingRectangle.Width>150&&w.Current.BoundingRectangle.Height>60)return w;Thread.Sleep(250);}throw new Exception("OWNED_WINDOW_NOT_FOUND");}
 static void Main(string[] args){Console.SetOut(new StreamWriter(Console.OpenStandardOutput(),new System.Text.UTF8Encoding(false)){AutoFlush=true});if(args[0]=="find-uninstaller"){foreach(AutomationElement e in AutomationElement.RootElement.FindAll(TreeScope.Children,new PropertyCondition(AutomationElement.ControlTypeProperty,ControlType.Window)))if(e.Current.Name.StartsWith("Agent Canary Community 3.0 candidate.",StringComparison.Ordinal)&&e.Current.BoundingRectangle.Width>150)Console.WriteLine(e.Current.ProcessId+"|"+e.Current.Name);return;}if(args[0]=="close-installed"){foreach(var p in Process.GetProcessesByName("AgentCanary"))try{if(string.Equals(p.MainModule.FileName,Path.GetFullPath(args[1]),StringComparison.OrdinalIgnoreCase)){p.CloseMainWindow();Console.WriteLine(p.Id);}}catch{}return;}int pid=int.Parse(args[1]);var w=Window(pid);
 if(args[0]=="capture"){var r=w.Current.BoundingRectangle;using(var b=new Bitmap((int)r.Width,(int)r.Height)){using(var g=Graphics.FromImage(b)){var dc=g.GetHdc();PrintWindow((IntPtr)w.Current.NativeWindowHandle,dc,2);g.ReleaseHdc(dc);}b.Save(args[2]);}return;}
 if(args[0]=="inspect"||args[0]=="inspect-controls"){foreach(AutomationElement e in w.FindAll(TreeScope.Descendants,Condition.TrueCondition)){if(e.Current.ControlType==ControlType.Button||e.Current.ControlType==ControlType.Edit||(args[0]=="inspect"&&e.Current.ControlType==ControlType.Text))Console.WriteLine(e.Current.AutomationId+"|"+e.Current.ControlType.ProgrammaticName+"|"+e.Current.IsEnabled+"|"+e.Current.Name);}return;}
 if(args[0]=="click"){var e=w.FindFirst(TreeScope.Descendants,new PropertyCondition(AutomationElement.NameProperty,args[2]));if(e==null||!e.Current.IsEnabled)throw new Exception("OWNED_CONTROL_MISSING_OR_DISABLED");((InvokePattern)e.GetCurrentPattern(InvokePattern.Pattern)).Invoke();return;}
 if(args[0]=="value"){var e=w.FindFirst(TreeScope.Descendants,new PropertyCondition(AutomationElement.AutomationIdProperty,args[2]));Console.WriteLine(((ValuePattern)e.GetCurrentPattern(ValuePattern.Pattern)).Current.Value);return;}
 if(args[0]=="set"){var e=w.FindFirst(TreeScope.Descendants,new PropertyCondition(AutomationElement.AutomationIdProperty,args[2]));if(e==null)throw new Exception("OWNED_CONTROL_NOT_FOUND");((ValuePattern)e.GetCurrentPattern(ValuePattern.Pattern)).SetValue(args[3]);return;}
 if(args[0]=="close"){((WindowPattern)w.GetCurrentPattern(WindowPattern.Pattern)).Close();return;}
 }
}
